#!/usr/bin/env python3
"""
Round nh3 (culprits), 16 October 2026, from the Invasion of non-humans chat.
Needs round nh2.

Files population density (ct_pop) a second time, under On-planet invasion >
Invasion of the living > Invasion of nonhumans, and updates the Invasion of
non-humans row's note. Changes map/app.js and map/test.mjs only.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round nh3 (16 October, the Invasion of non-humans chat)\n\nNeeds round nh2 (guards on its heading).\n\n- ct_pop (population density, GHSL) is filed a second time, under On-planet invasion > Invasion of\n  the living > Invasion of nonhumans, after nonhuman_atlas (asked 16 October); it stays under\n  Overpopulation too.\n- nonhuman_atlas's note lists the map's new parts: projected urban spread to 2100 under five SSPs\n  (Chen et al. 2020, PANGAEA, CC BY-NC-SA 4.0), development potential by sector (Oakleaf et al.\n  2019) and the Development Threat Index (SEDAC). Tiles nonhuman_urban2100.py and\n  nonhuman_devpotential.py. PADDD outlines now keep small shapes at every zoom (tippecanoe\n  --no-tiny-polygon-reduction) and the map rings them with a glow wider out.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("nonhuman3: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round nh2" not in h.read_text(encoding="utf-8"):
        sys.exit("nonhuman3: round nh2 must be applied first (nonhuman2_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("nonhuman3: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("nonhuman3: the diff did not apply:\n" + r.stdout + r.stderr)
        print("nonhuman3: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
